package com.example.starter.entity;

import java.math.BigDecimal;
import java.time.Instant;

/** 商户（合成数据）。 */
public class Merchant {
    private String merchantNo;
    private String merchantName;
    /** 手续费率，如 0.006000 表示千分之六。 */
    private BigDecimal feeRate;
    private String status;
    private Instant createdAt;

    public String getMerchantNo() { return merchantNo; }
    public void setMerchantNo(String merchantNo) { this.merchantNo = merchantNo; }
    public String getMerchantName() { return merchantName; }
    public void setMerchantName(String merchantName) { this.merchantName = merchantName; }
    public BigDecimal getFeeRate() { return feeRate; }
    public void setFeeRate(BigDecimal feeRate) { this.feeRate = feeRate; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
}

package com.example.starter.entity;

import java.time.Instant;
import java.time.LocalDate;

/** 日切清算批次。 */
public class SettlementBatch {
    private LocalDate batchDate;
    /** OPEN / CLOSED。 */
    private String status;
    private Instant closedAt;
    private int merchantCount;
    /** 金额单位：分。 */
    private long totalAmount;
    private long totalFee;
    private long settledAmount;
    private Instant createdAt;

    public LocalDate getBatchDate() { return batchDate; }
    public void setBatchDate(LocalDate batchDate) { this.batchDate = batchDate; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public Instant getClosedAt() { return closedAt; }
    public void setClosedAt(Instant closedAt) { this.closedAt = closedAt; }
    public int getMerchantCount() { return merchantCount; }
    public void setMerchantCount(int merchantCount) { this.merchantCount = merchantCount; }
    public long getTotalAmount() { return totalAmount; }
    public void setTotalAmount(long totalAmount) { this.totalAmount = totalAmount; }
    public long getTotalFee() { return totalFee; }
    public void setTotalFee(long totalFee) { this.totalFee = totalFee; }
    public long getSettledAmount() { return settledAmount; }
    public void setSettledAmount(long settledAmount) { this.settledAmount = settledAmount; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
}

package com.example.starter.entity;

import java.time.Instant;
import java.time.LocalDate;

/** 支付交易流水。 */
public class PaymentTxn {
    private Long id;
    private String requestId;
    private String fingerprint;
    private String channelFlowNo;
    private String merchantNo;
    /** 金额单位：分。 */
    private long amount;
    private long fee;
    private LocalDate batchDate;
    /** 调账前的原批次；非调账交易为 null。 */
    private LocalDate originBatchDate;
    /** POSTED / SUSPENDED / MOVED。 */
    private String status;
    private Instant occurredAt;
    private Instant createdAt;
    private Instant movedAt;

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getRequestId() { return requestId; }
    public void setRequestId(String requestId) { this.requestId = requestId; }
    public String getFingerprint() { return fingerprint; }
    public void setFingerprint(String fingerprint) { this.fingerprint = fingerprint; }
    public String getChannelFlowNo() { return channelFlowNo; }
    public void setChannelFlowNo(String channelFlowNo) { this.channelFlowNo = channelFlowNo; }
    public String getMerchantNo() { return merchantNo; }
    public void setMerchantNo(String merchantNo) { this.merchantNo = merchantNo; }
    public long getAmount() { return amount; }
    public void setAmount(long amount) { this.amount = amount; }
    public long getFee() { return fee; }
    public void setFee(long fee) { this.fee = fee; }
    public LocalDate getBatchDate() { return batchDate; }
