                                {"adjustNo":"HTTP-ADJ-1","channelFlowNo":"HTTP-FLOW-3",
                                 "fromBatchDate":"2026-09-20","toBatchDate":"2026-09-21"}"""))
                .andExpect(status().isCreated())
